using System;

namespace ZFrame.View
{
    /// <summary>
    /// One settings entry, fully described by data (TASK-A-M3-02). Adding an
    /// option to the UI = adding ONE definition line to a
    /// <see cref="SettingsPage"/> in <see cref="SettingsRegistry.BuildDefaults"/>
    /// — the row control is generated by <see cref="SettingsRowFactory"/> and
    /// no layout code changes. Plain C# class (no ScriptableObject) so the
    /// whole registry stays unit-testable without assets.
    ///
    /// Value semantics per <see cref="SettingType"/>:
    /// - Toggle: <see cref="DefaultValue"/>/<see cref="CurrentValue"/> is a <c>bool</c>;
    /// - Slider: a <c>float</c> clamped to [<see cref="Min"/>, <see cref="Max"/>];
    /// - Enum: an <c>int</c> index into <see cref="EnumOptions"/>;
    /// - Action: no value (null) — <see cref="Apply"/> is invoked directly on click;
    /// - Binding: no value (null) — <see cref="ActionKey"/> names the rebound
    ///   action, <see cref="BindingIndex"/> which binding of it (-1 = primary),
    ///   the override lives in <c>input_bindings.json</c> (A-M3-03/M3-04);
    /// - BindingReset: no value (null) — one map-wide "全部恢复默认" trigger;
    /// - Note: no value (null) — read-only explanatory text, no control (A-M3-04).
    ///
    /// <see cref="CurrentValue"/> is the display mirror maintained by
    /// <see cref="SettingsModel"/> (the model owns the authoritative state;
    /// the mirror exists so views/factories can read values without holding
    /// the model). <see cref="Apply"/> fires immediately on every committed
    /// change ("即时应用") — for options that persist only (gameplay /
    /// accessibility placeholders), pass null or a no-op and document the
    /// future consumer in the definition's XML doc.
    /// </summary>
    public sealed class SettingDefinition
    {
        /// <summary>Stable, persisted key (e.g. "video.vsync"). Unique across the whole registry.</summary>
        public string Id { get; }

        /// <summary>Localized display name shown on the row label / button.</summary>
        public string DisplayName { get; }

        /// <summary>Which row control the factory builds.</summary>
        public SettingType Type { get; }

        /// <summary>Factory-default value (see type semantics above; null for Action).</summary>
        public object DefaultValue { get; }

        /// <summary>Display mirror of the current value — kept in sync by <see cref="SettingsModel"/>.</summary>
        public object CurrentValue { get; set; }

        /// <summary>Slider lower bound (Slider only).</summary>
        public float Min { get; }

        /// <summary>Slider upper bound (Slider only).</summary>
        public float Max { get; }

        /// <summary>Display names of the enum choices, index == stored value (Enum only).</summary>
        public string[] EnumOptions { get; }

        /// <summary>
        /// Immediate-apply callback, invoked with the new value on every
        /// committed change (and again on Revert/Reset/Load re-apply). Null =
        /// store-only placeholder (document the future consumer in the page XML doc).
        /// </summary>
        public Action<object> Apply { get; }

        /// <summary>True = the new value only takes effect after an application restart (UI may hint this).</summary>
        public bool RequiresRestart { get; }

        /// <summary>
        /// Fully qualified action key this row rebinds ("Player/Interact",
        /// TASK-A-M3-03). Non-null for <see cref="SettingType.Binding"/> rows
        /// only; null for every other type.
        /// </summary>
        public string ActionKey { get; }

        /// <summary>
        /// Which binding of <see cref="ActionKey"/> this row owns (TASK-A-M3-04):
        /// -1 = "the action's primary binding" (the A-M3-03 behaviour, kept for
        /// single-binding actions), otherwise the exact index inside
        /// <c>InputAction.bindings</c> — how the four 移动 directions address
        /// the parts of the WASD composite.
        /// </summary>
        public int BindingIndex { get; }

        /// <summary>
        /// Optional interactability gate (TASK-B-R9-06): when non-null and it returns
        /// false, the row's control is created disabled. Used by the 插帧 row — an
        /// environment that cannot ever generate frames must not offer a switch that
        /// silently does nothing (same principle as the upscaler's capability suffix).
        /// Null (the default for every existing row) = always interactable.
        /// </summary>
        public Func<bool> Interactable { get; }

        private SettingDefinition(
            string id,
            string displayName,
            SettingType type,
            object defaultValue,
            float min,
            float max,
            string[] enumOptions,
            Action<object> apply,
            bool requiresRestart,
            string actionKey = null,
            int bindingIndex = -1,
            Func<bool> interactable = null)
        {
            if (string.IsNullOrEmpty(id))
            {
                throw new ArgumentException("setting id must not be null/empty", nameof(id));
            }

            if (string.IsNullOrEmpty(displayName))
            {
                throw new ArgumentException("setting display name must not be null/empty", nameof(id));
            }

            Id = id;
            DisplayName = displayName;
            Type = type;
            DefaultValue = defaultValue;
            CurrentValue = defaultValue;
            Min = min;
            Max = max;
            EnumOptions = enumOptions;
            Apply = apply;
            RequiresRestart = requiresRestart;
            ActionKey = actionKey;
            BindingIndex = bindingIndex;
            Interactable = interactable;
        }

        /// <summary>Creates a Toggle row definition.</summary>
        public static SettingDefinition Toggle(
            string id,
            string displayName,
            bool defaultValue,
            Action<object> apply = null,
            bool requiresRestart = false,
            Func<bool> interactable = null)
        {
            return new SettingDefinition(
                id, displayName, SettingType.Toggle, defaultValue, 0f, 1f, null, apply, requiresRestart,
                interactable: interactable);
        }

        /// <summary>Creates a Slider row definition; the default must lie within [min, max].</summary>
        public static SettingDefinition Slider(
            string id,
            string displayName,
            float defaultValue,
            float min,
            float max,
            Action<object> apply = null)
        {
            if (min > max)
            {
                throw new ArgumentException($"setting '{id}': min ({min}) must not exceed max ({max}).");
            }

            if (defaultValue < min || defaultValue > max)
            {
                throw new ArgumentException($"setting '{id}': default ({defaultValue}) outside [{min}, {max}].");
            }

            return new SettingDefinition(id, displayName, SettingType.Slider, defaultValue, min, max, null, apply, false);
        }

        /// <summary>Creates an Enum (Dropdown) row definition; the default index must be a valid option index.</summary>
        public static SettingDefinition EnumSetting(
            string id,
            string displayName,
            int defaultIndex,
            string[] options,
            Action<object> apply = null,
            bool requiresRestart = false)
        {
            if (options == null || options.Length == 0)
            {
                throw new ArgumentException($"setting '{id}': enum needs at least one option.", nameof(options));
            }

            if (defaultIndex < 0 || defaultIndex >= options.Length)
            {
                throw new ArgumentException($"setting '{id}': default index {defaultIndex} outside {options.Length} options.");
            }

            return new SettingDefinition(id, displayName, SettingType.Enum, defaultIndex, 0f, options.Length - 1, options, apply, requiresRestart);
        }

        /// <summary>Creates an Action (Button) row definition — an imperative trigger with no persisted value.</summary>
        public static SettingDefinition Action(
            string id,
            string displayName,
            Action<object> onTrigger = null)
        {
            return new SettingDefinition(id, displayName, SettingType.Action, null, 0f, 1f, null, onTrigger, false);
        }

        /// <summary>
        /// Creates a key-binding row (TASK-A-M3-03): label + current-key
        /// button + per-row 恢复默认 button. No persisted value here — the
        /// override is owned by <see cref="RebindService"/>.
        /// </summary>
        /// <param name="actionKey">Fully qualified action key ("Player/Interact").</param>
        /// <param name="bindingIndex">
        /// Binding index inside the action (TASK-A-M3-04). -1 (default) keeps the
        /// A-M3-03 semantics: "the action's primary binding". A concrete index
        /// addresses one part of a composite — the four 移动 rows use the W/A/S/D
        /// parts of <c>Player/Move</c>. The index must be RESOLVED FROM THE ASSET
        /// (path lookup, see <c>RebindService.FindBindingIndexByPath</c>), never
        /// hardcoded: asset binding order is data.
        /// </param>
        public static SettingDefinition Binding(
            string id, string displayName, string actionKey, int bindingIndex = -1)
        {
            if (string.IsNullOrEmpty(actionKey))
            {
                throw new ArgumentException($"setting '{id}': binding rows need an action key.", nameof(actionKey));
            }

            if (bindingIndex < -1)
            {
                throw new ArgumentException($"setting '{id}': binding index {bindingIndex} must be -1 (primary) or a real index.");
            }

            return new SettingDefinition(
                id, displayName, SettingType.Binding, null, 0f, 1f, null, null, false, actionKey, bindingIndex);
        }

        /// <summary>
        /// Creates a read-only explanatory line (TASK-A-M3-04) — a plain text
        /// row stating a limitation (e.g. 手柄摇杆使用默认设置，暂不支持重绑定).
        /// No control, no value, no callback: the row cannot pretend to offer
        /// something the input layer does not support.
        /// </summary>
        public static SettingDefinition Note(string id, string text)
        {
            return new SettingDefinition(id, text, SettingType.Note, null, 0f, 1f, null, null, false);
        }

        /// <summary>Creates the map-wide "全部恢复默认" row of the 操作 tab (no persisted value).</summary>
        public static SettingDefinition BindingReset(string id, string displayName)
        {
            return new SettingDefinition(id, displayName, SettingType.BindingReset, null, 0f, 1f, null, null, false);
        }

        /// <summary>Display name of the currently selected enum option (Enum rows only), or null.</summary>
        public string CurrentEnumOptionName()
        {
            if (Type != SettingType.Enum || EnumOptions == null)
            {
                return null;
            }

            int index = CurrentValue is int i ? i : 0;
            return index >= 0 && index < EnumOptions.Length ? EnumOptions[index] : null;
        }
    }
}
